[
  {
    "statement": "A study in the UK found that using a piscicide containing rotenone resulted in the eradication of the black bullhead population.",
    "citations": [
      "1050"
    ]
  },
  {
    "statement": "A study in the USA found that rotenone successfully eradicated black bullheads.",
    "citations": [
      "1050"
    ]
  },
  {
    "statement": "In a USA study on eradicating black bullheads, one of the two ponds studied required a second dose of rotenone.",
    "citations": [
      "1050"
    ]
  },
  {
    "statement": "There was no evidence found regarding the long-term impacts on native invertebrate communities following the eradication of black bullheads using rotenone.",
    "citations": []
  }
]

[
  {
    "statement": "A replicated, controlled study in Belgium found that introducing northern pike resulted in a significant decrease in the number of bullfrog tadpoles.",
    "citations": [
      "1039"
    ]
  },
  {
    "statement": "A replicated study in Belgium reported very low catchability of adult bullfrogs using a double fyke net over a 24-hour period.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "A small study in the USA found that adult bullfrogs can be captured overnight using a single floating trap.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "A replicated, controlled study in the USA observed that bullfrog populations quickly recovered after intensive removal of adults.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "A before-and-after study in France showed a significant reduction in the number of adult and juvenile bullfrogs when shooting of metamorphosed individuals was part of a combined treatment approach before reproduction.",
    "citations": [
      "1045"
    ]
  }
